INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('0689fd2e-b56c-4c35-adb5-e4ef34083174'::uuid, 'card_description', 'In 1911, explorer Hiram Bingham identified a forgotten place in the ruins on a ridge. Inca nobles once lived in the complex, a ceremonial center above the spot where two small rivers meet.', 'On a ridge above where two small rivers meet, Vitcos often housed the Neo-Inca rulers until 1572. Its location was later forgotten, until Hiram Bingham identified the ruins in 1911.', 'teaser-card-s036-rollback:0689fd2e-b56c-4c35-adb5-e4ef34083174:card_description', 'rollback of teaser-card-s036: card_description ''On a ridge above where two small rivers meet, Vitcos often housed the Neo-Inca rulers until 1572. Its location was later forgotten, until Hiram Bingham identified the ruins in 1911.'' restored on Vitcos', '6866f31ca41521e52dbcd6912a262a05998a91bb456aadd75831cbfcccdc4058|3df7ef0e632d30f253a6df233fbe5271029397817094707ff5b9cef80b78ead3|3df7ef0e632d30f253a6df233fbe5271029397817094707ff5b9cef80b78ead3', '[{"source": "lane WB run wb-shorts-pilot3-2026-10-20: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "In 1911, explorer Hiram Bingham identified a forgotten place in the ruins on a ridge. Inca nobles once lived in the complex, a ceremonial center above the spot where two small rivers meet."}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: checker card_fact_checker:teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "in 1911 the place was identified [S6]; the identification was made by the explorer Hiram Bingham [S6]; the place had been forgotten before that [S6]; the ruins lie on a ridge [S3]; Inca nobles once lived there [S1]; it was a ceremonial center [S1]; it stands above the confluence of two small rivers [S3]"}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "In 1911, explorer Hiram Bingham identified the place in the ruins [SUPPORTED: https://www.apacheta.fr/en/blog/inca-city-of-vitcos]; Hiram Bingham was an explorer [SUPPORTED: https://en.wikipedia.org/wiki/Hiram_Bingham_III]; The place had been forgotten [SUPPORTED: https://www.gutenberg.org/files/10772/10772-h/10772-h.htm]; The ruins are on a ridge [SUPPORTED: https://www.americanantiquarian.org/proceedings/45647892.pdf]; Inca nobles once lived in the complex [SUPPORTED: https://www.gutenberg.org/files/10772/10772-h/10772-h.htm]; The complex was a ceremonial center [SUPPORTED: https://www.apacheta.fr/en/blog/inca-city-of-vitcos]; The complex lies above the spot where two small rivers meet [SUPPORTED: https://www.gutenberg.org/files/10772/10772-h/10772-h.htm]"}]'::jsonb),
    ('08122cd2-522f-4ebc-b363-aabc7bd60de3'::uuid, 'card_description', 'A gold cup made this mound famous, though it is now ploughed away. Digs also found much earlier Neolithic activity, with by far the largest assemblage of grooved ware in the county.', 'The Ringlemere gold cup was found at Ringlemere Barrow near Sandwich, a mound now ploughed away that once stood as high as 5m, yet no burials of its own time have been found there.', 'teaser-card-s036-rollback:08122cd2-522f-4ebc-b363-aabc7bd60de3:card_description', 'rollback of teaser-card-s036: card_description ''The Ringlemere gold cup was found at Ringlemere Barrow near Sandwich, a mound now ploughed away that once stood as high as 5m, yet no burials of its own time have been found there.'' restored on Ringlemere Barrow', '2f05e3486a9ae94338ae5cb5191f8dba88f529fda12a63886c9b22621e74ad45|07b3995ccf149776e16f3e722def3c5caaaca74d8362105216e455c2f9447c52|07b3995ccf149776e16f3e722def3c5caaaca74d8362105216e455c2f9447c52', '[{"source": "lane WB run wb-shorts-pilot3-2026-10-20: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "A gold cup made this mound famous, though it is now ploughed away. Digs also found much earlier Neolithic activity, with by far the largest assemblage of grooved ware in the county."}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "the mound is famous for a gold cup (found there) [S1]; the mound is now ploughed away [S4]; excavations found evidence of much earlier Neolithic activity on the site [S3, S6]; the site yielded by far the largest assemblage of grooved ware in the county [S6]"}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "A gold cup made this mound (Ringlemere Barrow, England) famous. [SUPPORTED: https://www.kentarchaeology.org.uk/magazine/64/18-more-important-discoveries-at-ringlemere-farm]; The mound is now ploughed away. [SUPPORTED: https://www.kentarchaeology.org.uk/magazine/64/18-more-important-discoveries-at-ringlemere-farm]; Digs also found much earlier Neolithic activity. [SUPPORTED: https://www.kentarchaeology.org.uk/magazine/64/18-more-important-discoveries-at-ringlemere-farm]; The digs found by far the largest assemblage of grooved ware in the county. [SUPPORTED: https://www.kentarchaeology.org.uk/magazine/64/18-more-important-discoveries-at-ringlemere-farm]"}]'::jsonb),
    ('0dd83b62-fce8-4143-9d25-ed7de89933d8'::uuid, 'card_description', 'Iron blades of sickles or pruning hooks came from this hill fort. The British Museum now holds them, and the Iron Age fort tops an isolated limestone outcrop on the route of the Wansdyke.', 'On an isolated outcrop of Oolitic Limestone on the route of the Wansdyke, Stantonbury Camp was an Iron Age hill fort. Its iron sickle or pruning-hook blades now rest in the British Museum.', 'teaser-card-s036-rollback:0dd83b62-fce8-4143-9d25-ed7de89933d8:card_description', 'rollback of teaser-card-s036: card_description ''On an isolated outcrop of Oolitic Limestone on the route of the Wansdyke, Stantonbury Camp was an Iron Age hill fort. Its iron sickle or pruning-hook blades now rest in the British Museum.'' restored on Stantonbury Camp', '28f55e8c38092bcefa711dfb5fae812012d5bc3855def075622074476063ba38|fc078999fdbd193720c42abb79003582434d0a4051015aeb129ca5810d22d683|fc078999fdbd193720c42abb79003582434d0a4051015aeb129ca5810d22d683', '[{"source": "lane WB run wb-shorts-pilot3-2026-10-20: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "Iron blades of sickles or pruning hooks came from this hill fort. The British Museum now holds them, and the Iron Age fort tops an isolated limestone outcrop on the route of the Wansdyke."}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "iron blades of sickles or pruning hooks came from the site [S4]; the site is a hill fort [S1]; the British Museum now holds them [S4]; it is an Iron Age fort [S1]; the fort is at the top of an isolated limestone outcrop [S3]; the fort is on the route of the Wansdyke [S3]"}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "Iron blades of sickles or pruning hooks came from this hill fort (Stantonbury Camp, England). [SUPPORTED: https://artsandculture.google.com/asset/iron-farming-tools/IgGW7TKKe4nHYw?hl=en]; The finds are iron blades of sickles or pruning hooks. [SUPPORTED: https://artsandculture.google.com/asset/iron-farming-tools/IgGW7TKKe4nHYw?hl=en]; The British Museum now holds them. [SUPPORTED: https://artsandculture.google.com/asset/iron-farming-tools/IgGW7TKKe4nHYw?hl=en]; The fort is an Iron Age fort. [SUPPORTED: https://www.digitaldigging.net/stantonbury-camp-hillfort-somerset/]; The fort tops an isolated limestone outcrop. [SUPPORTED: https://app.bathnes.gov.uk/docs/temp/Planning-Policy/Evidence-Base/Urban-Design-Landscape-and-Heritage/RuralLandscapes-Chapter7.pdf]; The fort is on the route of the Wansdyke. [SUPPORTED: https://app.bathnes.gov.uk/docs/temp/Planning-Policy/Evidence-Base/Urban-Design-Landscape-and-Heritage/RuralLandscapes-Chapter7.pdf]"}]'::jsonb),
    ('0e7825f5-26f0-483e-8cd0-687a9228a894'::uuid, 'card_description', 'Like Pompeii, in 79 AD ash from Mount Vesuvius largely buried this ancient city. The city is most famous for the Roman villas found nearby, on a 50 m high headland over the Gulf of Naples.', 'Largely buried by tephra ash from Vesuvius in 79 AD, Stabiae is most famous for the Roman villas found near it, sited on a 50 m high headland overlooking the Gulf of Naples.', 'teaser-card-s036-rollback:0e7825f5-26f0-483e-8cd0-687a9228a894:card_description', 'rollback of teaser-card-s036: card_description ''Largely buried by tephra ash from Vesuvius in 79 AD, Stabiae is most famous for the Roman villas found near it, sited on a 50 m high headland overlooking the Gulf of Naples.'' restored on Stabiae', '675e266ac8737595f1b6fb33c085eaf44b911484841025ccff861a693996ea99|8f64c0f5bfc91c7ece6c0e3de1078bc7511cbf3bb1110d97c803f6b75b55064a|8f64c0f5bfc91c7ece6c0e3de1078bc7511cbf3bb1110d97c803f6b75b55064a', '[{"source": "lane WB run wb-shorts-pilot3-2026-10-20: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "Like Pompeii, in 79 AD ash from Mount Vesuvius largely buried this ancient city. The city is most famous for the Roman villas found nearby, on a 50 m high headland over the Gulf of Naples."}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "it is an ancient city [S1]; like Pompeii, it was largely buried by ash [S2]; the burial came from the 79 AD eruption of Mount Vesuvius [S2]; the city is most famous for the Roman villas found near it [S3]; the villas stand on a 50 m high headland [S4]; the headland overlooks the Gulf of Naples [S4]"}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "The city (Stabiae, Italy) is most famous for the Roman villas found nearby. [SUPPORTED: https://artsandculture.google.com/story/ancient-stabiae-italy-cyark/eAVRdJ_Q_C2tIA?hl=en]; Ash from Mount Vesuvius largely buried this ancient city. [SUPPORTED: https://pompeiisites.org/wp-content/uploads/Mappa-Stabiae-eng.pdf]; The burial happened in 79 AD. [SUPPORTED: https://artsandculture.google.com/story/ancient-stabiae-italy-cyark/eAVRdJ_Q_C2tIA?hl=en]; The city was buried like Pompeii. [SUPPORTED: https://openheritage3d.org/project.php?id=6spz-ee90]; The villas are on a headland. [SUPPORTED: https://www.afs.enea.it/protprev/www/cases/varano/testo.htm]; The headland is 50 m high. [SUPPORTED: https://www.afs.enea.it/protprev/www/cases/varano/testo.htm]; The headland is over the Gulf of Naples. [SUPPORTED: https://artsandculture.google.com/story/ancient-stabiae-italy-cyark/eAVRdJ_Q_C2tIA?hl=en]"}]'::jsonb),
    ('12851166-9039-4782-b5e3-98bce8e3ccc7'::uuid, 'card_description', 'The city''s patron goddess got a temple outside the city walls. Within the walls lies one of the best preserved grid-plan cities in the country, with an agora, a theatre and private houses.', 'Ancient Kassope, built on a Hippodamian grid—one of the best surviving examples in the Hellenic world. A temple to Aphrodite stood among its Cyclopean walls.', 'teaser-card-s036-rollback:12851166-9039-4782-b5e3-98bce8e3ccc7:card_description', 'rollback of teaser-card-s036: card_description ''Ancient Kassope, built on a Hippodamian grid—one of the best surviving examples in the Hellenic world. A temple to Aphrodite stood among its Cyclopean walls.'' restored on Temple of Aphrodite, Ancient Cassope', '4484a1999ee8b86140ae30548f12043cdb62816905427029818fc5ef2741e805|1f2c35c6809afd618e6953eb08b3ccc607670b689b86d331721d1179de39712e|1f2c35c6809afd618e6953eb08b3ccc607670b689b86d331721d1179de39712e', '[{"source": "lane WB run wb-shorts-pilot3-2026-10-20: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "The city''s patron goddess got a temple outside the city walls. Within the walls lies one of the best preserved grid-plan cities in the country, with an agora, a theatre and private houses."}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: checker card_fact_checker:teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "the temple belonged to the city''s patron goddess [S2]; the temple stands outside the city walls [S1]; the city lies within walls [S1, S3]; the city is one of the best-preserved grid-plan cities in the country [S3]; the city has an agora [S3]; the city has a theatre [S3]; the city has private houses [S3]"}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "The city''s patron goddess got a temple outside the city walls [SUPPORTED: https://ancient-greece.org/archaeology/kassope/]; The temple belonged to the city''s patron goddess [SUPPORTED: https://www.roamintheempire.com/index.php/2022/06/29/cassope/]; The temple stood outside the city walls [SUPPORTED: https://www.roamintheempire.com/index.php/2022/06/29/cassope/]; Within the walls lies a grid-plan city [SUPPORTED: https://www.roamintheempire.com/index.php/2022/06/29/cassope/]; It is one of the best preserved grid-plan cities in the country [SUPPORTED: https://ancient-greece.org/archaeology/kassope/]; The city within the walls has an agora [SUPPORTED: https://ancient-greece.org/archaeology/kassope/]; The city within the walls has a theatre [SUPPORTED: https://ancient-greece.org/archaeology/kassope/]; The city within the walls has private houses [SUPPORTED: https://www.roamintheempire.com/index.php/2022/06/29/cassope/]"}]'::jsonb),
    ('19dcdb91-8d2c-43a7-acae-e7d709c576fe'::uuid, 'card_description', 'Around 1664, William Dugdale drew two standing stones by one entrance of this henge. By the time William Stukeley saw the Neolithic monument, both stones had disappeared.', 'A sketch from around 1664 shows two standing stones at the northwest entrance of King Arthur''s Round Table, a Neolithic henge in Cumbria. By 1725 they had disappeared.', 'teaser-card-s036-rollback:19dcdb91-8d2c-43a7-acae-e7d709c576fe:card_description', 'rollback of teaser-card-s036: card_description "A sketch from around 1664 shows two standing stones at the northwest entrance of King Arthur''s Round Table, a Neolithic henge in Cumbria. By 1725 they had disappeared." restored on King Arthur''s Round Table', '2f39de4d5e71156b7af02f22a4a06d71758d3f21fc205005a886b234623de2ca|95528151830563bd7c6fdcfdd53fd70001e25eb135e9e5aa2ea8d63d0731e268|95528151830563bd7c6fdcfdd53fd70001e25eb135e9e5aa2ea8d63d0731e268', '[{"source": "lane WB run wb-shorts-pilot3-2026-10-20: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "Around 1664, William Dugdale drew two standing stones by one entrance of this henge. By the time William Stukeley saw the Neolithic monument, both stones had disappeared."}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "around 1664 William Dugdale drew the site [S5]; his drawing shows two standing stones by one entrance [S5]; it is a henge [S1]; it is a Neolithic monument [S1]; William Stukeley later saw the monument [S6]; by then both stones had disappeared [S6]"}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "William Dugdale drew two standing stones by one entrance of this henge (King Arthur''s Round Table, England). [SUPPORTED: https://heritageaction.wordpress.com/2023/08/22/king-arthurs-round-table-eamont-bridge-cumbria/]; Dugdale''s drawing was made around 1664. [SUPPORTED: https://heritageaction.wordpress.com/2023/08/22/king-arthurs-round-table-eamont-bridge-cumbria/]; The two standing stones stood by one entrance of the monument. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/king-arthurs-round-table/history/]; The monument is a henge. [SUPPORTED: https://www.cambridge.org/core/journals/antiquaries-journal/article/king-arthurs-round-table-eamont-bridge-cumbria-the-excavation-of-an-excavation/3B1DC82DCFEE2B635D31C02B2EC2475F]; William Stukeley saw the monument. [SUPPORTED: https://heritageaction.wordpress.com/2023/08/22/king-arthurs-round-table-eamont-bridge-cumbria/]; By the time Stukeley saw it, both stones had disappeared. [SUPPORTED: https://heritageaction.wordpress.com/2023/08/22/king-arthurs-round-table-eamont-bridge-cumbria/]; The monument is Neolithic. [SUPPORTED: https://www.cambridge.org/core/journals/antiquaries-journal/article/king-arthurs-round-table-eamont-bridge-cumbria-the-excavation-of-an-excavation/3B1DC82DCFEE2B635D31C02B2EC2475F]"}]'::jsonb),
    ('2051a8ae-6ce5-4a33-bfa6-997ed2479750'::uuid, 'card_description', 'The country''s Three Mysteries include this shrine on a mountain slope. The others are a salt cauldron and a halberd at two other shrines; this one reveres a massive stone structure.', 'Shinto shrine beside an ancient quarry, famous for a huge man-carved rectangular stone of unknown purpose. The massive block cut from the living quarry face has defied explanation since records began.', 'teaser-card-s036-rollback:2051a8ae-6ce5-4a33-bfa6-997ed2479750:card_description', 'rollback of teaser-card-s036: card_description ''Shinto shrine beside an ancient quarry, famous for a huge man-carved rectangular stone of unknown purpose. The massive block cut from the living quarry face has defied explanation since records began.'' restored on Oushiko Shrine', '8309e7c93db1f6a457e927b1307468c0ecd8e7700de192610c94f68aa2884e4c|bc29d408b84f709344f3e473ffc5645f233bf8ce0eb332b350c53a7700fe1d11|bc29d408b84f709344f3e473ffc5645f233bf8ce0eb332b350c53a7700fe1d11', '[{"source": "lane WB run wb-shorts-pilot3-2026-10-20: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "The country''s Three Mysteries include this shrine on a mountain slope. The others are a salt cauldron and a halberd at two other shrines; this one reveres a massive stone structure."}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: checker card_fact_checker:teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "the shrine is one of the country''s Three Mysteries [S3]; the shrine lies on a mountain slope [S1]; the other two Mysteries are a salt cauldron and a halberd [S3]; those two belong to two other shrines [S3]; this shrine reveres a massive stone structure [S2]"}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "The country''s Three Mysteries include this shrine. [SUPPORTED: https://ja.wikipedia.org/wiki/%E7%94%9F%E7%9F%B3%E7%A5%9E%E7%A4%BE]; The shrine is on a mountain slope. [SUPPORTED: https://ja.wikipedia.org/wiki/%E7%94%9F%E7%9F%B3%E7%A5%9E%E7%A4%BE]; One of the other Three Mysteries is a salt cauldron at another shrine. [SUPPORTED: https://ja.wikipedia.org/wiki/%E7%94%9F%E7%9F%B3%E7%A5%9E%E7%A4%BE]; The other of the Three Mysteries is a halberd at another shrine. [SUPPORTED: https://ja.wikipedia.org/wiki/%E7%94%9F%E7%9F%B3%E7%A5%9E%E7%A4%BE]; This shrine reveres a massive stone structure. [SUPPORTED: https://ja.wikipedia.org/wiki/%E7%94%9F%E7%9F%B3%E7%A5%9E%E7%A4%BE]"}]'::jsonb),
    ('21c25d59-fe0a-4320-8e9d-96e9eea5ed67'::uuid, 'card_description', 'A coat of white limestone, now lost, once covered this brick arch. Once a triple arch, the Roman triumphal arch spanned the Appian Way as a symbolic entrance to the city.', 'Once a triple arch spanning the Appian Way, the brick Arch of Hadrian has lost its white limestone coating. Three pylons and one side arch remain, and no one knows its dedication.', 'teaser-card-s036-rollback:21c25d59-fe0a-4320-8e9d-96e9eea5ed67:card_description', 'rollback of teaser-card-s036: card_description ''Once a triple arch spanning the Appian Way, the brick Arch of Hadrian has lost its white limestone coating. Three pylons and one side arch remain, and no one knows its dedication.'' restored on Arch of Hadrian, Capua', 'd0a3fd1d36f8788d5cea087359e48c34ec4b874d1d617347bc1db54b663ec5e3|30dfd5a633d9a965977fafc4b7ab1627ff61ecb425ad4cde38efad9b4cc5113f|30dfd5a633d9a965977fafc4b7ab1627ff61ecb425ad4cde38efad9b4cc5113f', '[{"source": "lane WB run wb-shorts-pilot3-2026-10-20: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "A coat of white limestone, now lost, once covered this brick arch. Once a triple arch, the Roman triumphal arch spanned the Appian Way as a symbolic entrance to the city."}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: checker card_fact_checker:teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "the arch is built of brick [S5]; a coat of white limestone originally covered it [S5]; that coating is now lost [S5]; it was originally a triple arch [S2]; it is a Roman triumphal arch [S1]; it spanned the Appian Way [S3]; it served as an ideal (symbolic) entrance to the city [S3]"}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "A coat of white limestone once covered this brick arch. [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Hadrian_(Capua)]; The coat of white limestone is now lost. [SUPPORTED: https://www.treccani.it/enciclopedia/santa-maria-capua-vetere_(Enciclopedia-Italiana)/]; The arch is built of brick. [SUPPORTED: https://www.treccani.it/enciclopedia/santa-maria-capua-vetere_(Enciclopedia-Italiana)/]; It was once a triple arch. [SUPPORTED: https://www.treccani.it/enciclopedia/santa-maria-capua-vetere_(Enciclopedia-Italiana)/]; It is a Roman triumphal arch. [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Hadrian_(Capua)]; The arch spanned the Appian Way. [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Hadrian_(Capua)]; The arch was a symbolic entrance to the city. [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Hadrian_(Capua)]"}]'::jsonb),
    ('45fcb351-64fb-488a-ab19-35741221bf81'::uuid, 'card_description', 'The earliest inscription found here was for a statue of Emperor Hadrian. Soldiers from Chalcis in Syria made that dedication in about 126 AD, at a Roman fort on the fringe of the Sahara.', 'On the Sahara''s fringe lies Gemellae Fortress Roman, a rectangular fort with walls mostly about 3 metres thick, where a cohort from Syria honoured Hadrian with a statue in about 126 AD.', 'teaser-card-s036-rollback:45fcb351-64fb-488a-ab19-35741221bf81:card_description', 'rollback of teaser-card-s036: card_description "On the Sahara''s fringe lies Gemellae Fortress Roman, a rectangular fort with walls mostly about 3 metres thick, where a cohort from Syria honoured Hadrian with a statue in about 126 AD." restored on Gemellae Fortress Roman', '2cc92f8e4e3deeb8aee9c8787b1f6d32cca994a1142b35a03e0f3e20fc796f03|727225b6cd5d43bf50880d641f366a61682906325a53f8f5e289b9e6d77be243|727225b6cd5d43bf50880d641f366a61682906325a53f8f5e289b9e6d77be243', '[{"source": "lane WB run wb-shorts-pilot3-2026-10-20: writer card_writer:teaser-write-002", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "The earliest inscription found here was for a statue of Emperor Hadrian. Soldiers from Chalcis in Syria made that dedication in about 126 AD, at a Roman fort on the fringe of the Sahara."}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: checker card_fact_checker:teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "the earliest inscription found at the site [S4]; it was for a statue of Emperor Hadrian [S4]; the dedication was made by soldiers of a unit originating from Chalcis in Syria [S4]; it dates to about 126 AD [S4]; the site is a Roman fort [S1]; the fort lies on the fringe of the Sahara [S1]"}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "The earliest inscription found here was for a statue of Emperor Hadrian [SUPPORTED: https://books.openedition.org/cvz/6627?lang=en]; Soldiers made that dedication [SUPPORTED: https://books.openedition.org/cvz/6627?lang=en]; The soldiers were from Chalcis [SUPPORTED: https://de.wikipedia.org/wiki/Cohors_I_Chalcidenorum]; Chalcis is in Syria [SUPPORTED: https://www.cassiciaco.it/navigazione/africa/siti_archeologici/gemellae.html]; The dedication was made in about 126 AD [SUPPORTED: https://www.cassiciaco.it/navigazione/africa/siti_archeologici/gemellae.html]; The site is a Roman fort [SUPPORTED: https://www.persee.fr/doc/crai_0065-0536_1948_num_92_3_78299]; The fort is on the fringe of the Sahara [SUPPORTED: https://www.persee.fr/doc/crai_0065-0536_1949_num_93_3_78417]"}]'::jsonb),
    ('48767303-6f43-4ddb-88e5-fb43ea3dfd89'::uuid, 'card_description', 'The first Roman mosaic in Britain with scenes from the Trojan War lies at this villa. Photos of the villa''s cropmarks were taken in June 2018 and later made widely available on Google Earth.', 'First seen as cropmarks on Google Earth in June 2018, the Rutland Roman Villa holds a mosaic of scenes from the Trojan War, the first in Britain, 11 metres by nearly 7 metres.', 'teaser-card-s036-rollback:48767303-6f43-4ddb-88e5-fb43ea3dfd89:card_description', 'rollback of teaser-card-s036: card_description ''First seen as cropmarks on Google Earth in June 2018, the Rutland Roman Villa holds a mosaic of scenes from the Trojan War, the first in Britain, 11 metres by nearly 7 metres.'' restored on Rutland Roman Villa', '6e1f09467d4d1d5d0c948e89432efcacb8b4b5d5d31ef8a54f1a81b921ca8606|e1597e319fa13bed21949542a5d46837e37a3b2c9f3903bb0befdf188f3c0ca2|e1597e319fa13bed21949542a5d46837e37a3b2c9f3903bb0befdf188f3c0ca2', '[{"source": "lane WB run wb-shorts-pilot3-2026-10-20: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "The first Roman mosaic in Britain with scenes from the Trojan War lies at this villa. Photos of the villa''s cropmarks were taken in June 2018 and later made widely available on Google Earth."}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: checker card_fact_checker:teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "the villa has a Roman mosaic with scenes from the Trojan War [S2]; it is the first such mosaic in Britain [S2]; the site is a villa [S1]; the villa''s cropmarks were photographed in June 2018 [S4, W1]; the photos were later made widely available on Google Earth [W1]"}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "The first Roman mosaic in Britain with scenes from the Trojan War lies at this villa [SUPPORTED: https://theconversation.com/rutland-roman-villa-how-we-found-one-of-the-most-significant-mosaics-discovered-in-the-uk-196093]; The mosaic is the first of its kind in Britain [SUPPORTED: https://peterborougharchaeology.org/rutland-roman-villa-mosaic/]; The mosaic shows scenes from the Trojan War [SUPPORTED: https://www.cambridge.org/core/services/aop-cambridge-core/content/view/AF6081088C925F10AB0DC670A7540A7D/S0068113X25100342a.pdf/troy_story_the_ketton_mosaic_aeschylus_and_greek_mythography_in_late_roman_britain.pdf]; The mosaic still lies at the villa [SUPPORTED: https://www.cambridge.org/core/services/aop-cambridge-core/content/view/AF6081088C925F10AB0DC670A7540A7D/S0068113X25100342a.pdf/troy_story_the_ketton_mosaic_aeschylus_and_greek_mythography_in_late_roman_britain.pdf]; The site is a Roman villa [SUPPORTED: https://theconversation.com/rutland-roman-villa-how-we-found-one-of-the-most-significant-mosaics-discovered-in-the-uk-196093]; Photos of the villa''s cropmarks were taken in June 2018 [SUPPORTED: https://www.cambridge.org/core/services/aop-cambridge-core/content/view/AF6081088C925F10AB0DC670A7540A7D/S0068113X25100342a.pdf/troy_story_the_ketton_mosaic_aeschylus_and_greek_mythography_in_late_roman_britain.pdf]; The photos were later made widely available on Google Earth [SUPPORTED: https://www.cambridge.org/core/services/aop-cambridge-core/content/view/AF6081088C925F10AB0DC670A7540A7D/S0068113X25100342a.pdf/troy_story_the_ketton_mosaic_aeschylus_and_greek_mythography_in_late_roman_britain.pdf]"}, {"source": "web fact W1", "url": "https://www.cambridge.org/core/services/aop-cambridge-core/content/view/AF6081088C925F10AB0DC670A7540A7D/S0068113X25100342a.pdf/troy-story-the-ketton-mosaic-aeschylus-and-greek-mythography-in-late-roman-britain.pdf", "quote": "These cropmarks had been photographed in June 2018 and made widely available via Google Earth earlier in 2020, when they were reported to Leicestershire County Council"}]'::jsonb),
    ('5bb2f3b5-7bc6-4cf8-a3b4-cbb4b6e35595'::uuid, 'card_description', 'Described as Britain''s oldest road, this trackway has a stretch on a chalk ridge. Iron Age people built hillforts along the track, and that stretch runs to the Thames at the Goring Gap.', 'Described as Britain''s oldest road, the Ridgeway has carried travellers for at least 5,000 years along a high chalk ridge, where Iron Age hillforts once guarded the trading route.', 'teaser-card-s036-rollback:5bb2f3b5-7bc6-4cf8-a3b4-cbb4b6e35595:card_description', 'rollback of teaser-card-s036: card_description "Described as Britain''s oldest road, the Ridgeway has carried travellers for at least 5,000 years along a high chalk ridge, where Iron Age hillforts once guarded the trading route." restored on The Ridgeway', 'ce4f3d862c7c8410906f96323b06c7fa3d27c8d3202d097543c3b6a349da88a0|7e5f6eeaafeb73cb8f297c7f067066b414e4d769cb6e204eb756fdd02103f6b2|7e5f6eeaafeb73cb8f297c7f067066b414e4d769cb6e204eb756fdd02103f6b2', '[{"source": "lane WB run wb-shorts-pilot3-2026-10-20: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "Described as Britain''s oldest road, this trackway has a stretch on a chalk ridge. Iron Age people built hillforts along the track, and that stretch runs to the Thames at the Goring Gap."}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: checker card_fact_checker:teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "it is described as Britain''s oldest road [S1]; it is a trackway [S1]; a stretch of it runs on a chalk ridge [S2]; Iron Age people built hillforts along it [S6]; that stretch runs to the Thames at the Goring Gap [S2]"}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "This trackway is described as Britain''s oldest road [SUPPORTED: https://www.nationaltrail.co.uk/en_GB/trails/the-ridgeway/]; It is a trackway [SUPPORTED: https://www.nationaltrail.co.uk/en_GB/trails/the-ridgeway/]; The trackway has a stretch on a chalk ridge [SUPPORTED: https://www.nationaltrail.co.uk/en_GB/trails/the-ridgeway/]; Iron Age people built hillforts along the track [SUPPORTED: https://www.nationaltrail.co.uk/en_GB/trails/the-ridgeway/route/]; The hillforts along the track date from the Iron Age [SUPPORTED: https://britishheritage.com/travel/the-ridgeway-britains-oldest-highway]; That stretch runs to the Thames at the Goring Gap [SUPPORTED: https://en.wikipedia.org/wiki/Goring_Gap]"}]'::jsonb),
    ('679e85b1-245b-40bc-b815-8cd1ae71ee12'::uuid, 'card_description', 'Swimming and diving are banned over this island''s ruins. The partly submerged ruins belong to the ancient settlement of Dolichiste, and the area was declared specially protected in 1990.', 'A Lycian island whose northern coast is a sunken city. Kekova holds a port, two docks, three churches, two chapels, a bath, two towers, four production workshops, and Lycian sarcophagi in the sea.', 'teaser-card-s036-rollback:679e85b1-245b-40bc-b815-8cd1ae71ee12:card_description', 'rollback of teaser-card-s036: card_description ''A Lycian island whose northern coast is a sunken city. Kekova holds a port, two docks, three churches, two chapels, a bath, two towers, four production workshops, and Lycian sarcophagi in the sea.'' restored on Kekova Island', '1e653ac831d88fe077803c846b7713d46fe0f59bcaacdd94b4bc829f32166bfd|0f111d41a2a9310e4eb1ba4c164bcc5369381436fa2630e6480543e1810a3eb9|0f111d41a2a9310e4eb1ba4c164bcc5369381436fa2630e6480543e1810a3eb9', '[{"source": "lane WB run wb-shorts-pilot3-2026-10-20: writer card_writer:teaser-write-002", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "Swimming and diving are banned over this island''s ruins. The partly submerged ruins belong to the ancient settlement of Dolichiste, and the area was declared specially protected in 1990."}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: checker card_fact_checker:teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "swimming and diving are prohibited over the ruins [S2]; the site is an island with ruins [S1]; the ruins are partly submerged [S1]; the ruins belong to the ancient settlement of Dolichiste [S1]; the area was declared a specially protected area in 1990 [S2]"}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "The ruins on this island belong to the ancient settlement of Dolichiste [SUPPORTED: https://lycianway.co.uk/kekova]; The ruins are partly submerged [SUPPORTED: https://tr.wikipedia.org/wiki/Kekova]; Swimming is banned over this island''s ruins [SUPPORTED: https://lycianway.co.uk/kekova]; Diving is banned over this island''s ruins [SUPPORTED: https://lycianway.co.uk/kekova]; The area was declared specially protected [SUPPORTED: https://tvk.csb.gov.tr/kas-kekova-i-396]; The area was declared specially protected in 1990 [SUPPORTED: https://tvk.csb.gov.tr/kas-kekova-i-396]"}]'::jsonb),
    ('6cc9e902-c82f-4b21-9f36-41c2b783cebc'::uuid, 'card_description', 'Legal assemblies gathered at this crossroads of major trade routes. The routes linked Lake Malar communities with the north, and the country''s largest burial mound rises nearby.', 'Near Anundshögen — the ship-shaped burial mound of legendary King Anund, among Scandinavia''s larger such monuments. Norse saga tradition ties this site to a king whose name recurs across the region.', 'teaser-card-s036-rollback:6cc9e902-c82f-4b21-9f36-41c2b783cebc:card_description', 'rollback of teaser-card-s036: card_description "Near Anundshögen — the ship-shaped burial mound of legendary King Anund, among Scandinavia''s larger such monuments. Norse saga tradition ties this site to a king whose name recurs across the region." restored on Furby', 'b5d8134fd51e3bf154f485a3fae919a1935ea51d63ad789dc300d67a5ec66fab|202a49b2738e09a80351efe14014b3db8e0842896ed6f26ffa46e547ad89278c|202a49b2738e09a80351efe14014b3db8e0842896ed6f26ffa46e547ad89278c', '[{"source": "lane WB run wb-shorts-pilot3-2026-10-20: writer card_writer:teaser-rewrite2-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "Legal assemblies gathered at this crossroads of major trade routes. The routes linked Lake Malar communities with the north, and the country''s largest burial mound rises nearby."}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: checker card_fact_checker:teaser-check2-001 (check2), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "legal assemblies gathered at this place [S2]; the place lay at a crossroads of major trade routes [S2]; the routes linked Lake Malar communities with northern regions [S2]; the country''s largest burial mound is nearby [S1]"}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "Legal assemblies gathered at this crossroads [SUPPORTED: https://www.anundshog.se/spraksidor/english/about.4.18a7cdc416d6d4515e255d8f.html]; This place was a crossroads of routes [SUPPORTED: https://www.anundshog.se/spraksidor/english/about.4.18a7cdc416d6d4515e255d8f.html]; The routes were major trade routes [SUPPORTED: https://www.anundshog.se/spraksidor/english/about.4.18a7cdc416d6d4515e255d8f.html]; The routes linked Lake Malar communities with the north [SUPPORTED: https://www.anundshog.se/spraksidor/english/about.4.18a7cdc416d6d4515e255d8f.html]; The country''s largest burial mound rises nearby [SUPPORTED: https://www.anundshog.se/spraksidor/english/about.4.18a7cdc416d6d4515e255d8f.html]; The burial mound is near this place [SUPPORTED: https://www.werbeka.com/vasteras/bo/furbykrs.htm]"}]'::jsonb),
    ('728762be-061a-4f8a-b03f-980153495b02'::uuid, 'card_description', 'When Constantius Chlorus moved to the city, he renovated this Roman arena. The arena, dug into a hillside and built into what was then the city''s wall, could hold about 20,000 spectators.', 'Dug into the side of a hill, the Trier Amphitheatre could hold approximately 20,000 spectators. On its eastern bank, a small burial ground found in 1996 held the graves of 46 people.', 'teaser-card-s036-rollback:728762be-061a-4f8a-b03f-980153495b02:card_description', 'rollback of teaser-card-s036: card_description ''Dug into the side of a hill, the Trier Amphitheatre could hold approximately 20,000 spectators. On its eastern bank, a small burial ground found in 1996 held the graves of 46 people.'' restored on Trier Amphitheatre', 'dede2dbe4a3b9203d2cf750bc1a90749569e331226302994b9b0761249a06e5e|cdc664645ea82fceedd805a2e53c8a8892fd53576463f674609c51d6df216149|cdc664645ea82fceedd805a2e53c8a8892fd53576463f674609c51d6df216149', '[{"source": "lane WB run wb-shorts-pilot3-2026-10-20: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "When Constantius Chlorus moved to the city, he renovated this Roman arena. The arena, dug into a hillside and built into what was then the city''s wall, could hold about 20,000 spectators."}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: checker card_fact_checker:teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "Constantius Chlorus moved to the city [S5]; he renovated the arena [S5]; it is a Roman arena (amphitheatre) [S1]; the arena is dug into a hillside [S2]; it was built into what was then the city''s wall [S4]; it could hold about 20,000 spectators [S3]"}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/