    ('f29afd0d-6fb8-4405-bee8-c1b17a6989e3'::uuid, 'card_description', 'A mound 15 metres high is the highest structure left at this Maya site. The mound dates to the Late Formative, when the site became a regional political center on the New River.', 'On the New River, halfway between Cerros and Lamanai, lies San Estevan, a Maya regional political center from the Late Formative on, where Mound XV still rises 15 m, the highest remaining.', 'teaser-card-s036-rollback:f29afd0d-6fb8-4405-bee8-c1b17a6989e3:card_description', 'rollback of teaser-card-s036: card_description ''On the New River, halfway between Cerros and Lamanai, lies San Estevan, a Maya regional political center from the Late Formative on, where Mound XV still rises 15 m, the highest remaining.'' restored on San Estevan', 'e41c3945a3d7fc48e6accaf7e694d134786d7cda852150231074159a85f59e1b|ba125b1239c5b8b294c0e2d67d0d0a75431d040b41254f9ab4a75a51f42ef062|ba125b1239c5b8b294c0e2d67d0d0a75431d040b41254f9ab4a75a51f42ef062', '[{"source": "lane WB run wb-shorts-pilot3-2026-10-20: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "A mound 15 metres high is the highest structure left at this Maya site. The mound dates to the Late Formative, when the site became a regional political center on the New River."}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "a mound at the site is 15 metres high [S7]; the mound is the highest structure remaining at the site [S7]; it is a Maya site [S2]; the mound dates to the Late Formative period [S7]; from the Late Formative the site was a regional political center [S4]; the site is on the New River [S3]"}, {"source": "lane WB run wb-shorts-pilot3-2026-10-20: verifier card_web_verifier:teaser-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot3-2026-10-20/OUTCOMES.jsonl", "quote": "A mound 15 metres high is the highest structure left at this site. [SUPPORTED: https://web.archive.org/web/20250321074144/https://www.albany.edu/anthropology/research/san-estevan-archaeological-project]; The mound is 15 metres high. [SUPPORTED: https://web.archive.org/web/20250321074144/https://www.albany.edu/anthropology/research/san-estevan-archaeological-project]; This is a Maya site. [SUPPORTED: https://www.nbcnews.com/news/all/2-300-year-old-maya-pyramid-bulldozed-belize-road-project-flna1C9916550]; The mound dates to the Late Formative. [SUPPORTED: https://www.cambridge.org/core/journals/latin-american-antiquity/article/abs/reassessing-san-estevans-role-in-the-late-formative-political-geography-of-northern-belize/1A3890D23D71C6BCA2DF786ADEB6109F]; In the Late Formative the site became a regional political center. [SUPPORTED: https://web.archive.org/web/20250321074144/https://www.albany.edu/anthropology/research/san-estevan-archaeological-project]; The site is on the New River. [SUPPORTED: https://web.archive.org/web/20250321074144/https://www.albany.edu/anthropology/research/san-estevan-archaeological-project]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 20;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s036-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s036-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s036-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 20 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK of the reversal: the reversal must leave nothing behind either
WITH planned(site_id, column_name, written) AS (VALUES ('0689fd2e-b56c-4c35-adb5-e4ef34083174'::uuid, 'card_description', 'In 1911, explorer Hiram Bingham identified a forgotten place in the ruins on a ridge. Inca nobles once lived in the complex, a ceremonial center above the spot where two small rivers meet.'), ('08122cd2-522f-4ebc-b363-aabc7bd60de3'::uuid, 'card_description', 'A gold cup made this mound famous, though it is now ploughed away. Digs also found much earlier Neolithic activity, with by far the largest assemblage of grooved ware in the county.'), ('0dd83b62-fce8-4143-9d25-ed7de89933d8'::uuid, 'card_description', 'Iron blades of sickles or pruning hooks came from this hill fort. The British Museum now holds them, and the Iron Age fort tops an isolated limestone outcrop on the route of the Wansdyke.'), ('0e7825f5-26f0-483e-8cd0-687a9228a894'::uuid, 'card_description', 'Like Pompeii, in 79 AD ash from Mount Vesuvius largely buried this ancient city. The city is most famous for the Roman villas found nearby, on a 50 m high headland over the Gulf of Naples.'), ('12851166-9039-4782-b5e3-98bce8e3ccc7'::uuid, 'card_description', 'The city''s patron goddess got a temple outside the city walls. Within the walls lies one of the best preserved grid-plan cities in the country, with an agora, a theatre and private houses.'), ('19dcdb91-8d2c-43a7-acae-e7d709c576fe'::uuid, 'card_description', 'Around 1664, William Dugdale drew two standing stones by one entrance of this henge. By the time William Stukeley saw the Neolithic monument, both stones had disappeared.'), ('2051a8ae-6ce5-4a33-bfa6-997ed2479750'::uuid, 'card_description', 'The country''s Three Mysteries include this shrine on a mountain slope. The others are a salt cauldron and a halberd at two other shrines; this one reveres a massive stone structure.'), ('21c25d59-fe0a-4320-8e9d-96e9eea5ed67'::uuid, 'card_description', 'A coat of white limestone, now lost, once covered this brick arch. Once a triple arch, the Roman triumphal arch spanned the Appian Way as a symbolic entrance to the city.'), ('45fcb351-64fb-488a-ab19-35741221bf81'::uuid, 'card_description', 'The earliest inscription found here was for a statue of Emperor Hadrian. Soldiers from Chalcis in Syria made that dedication in about 126 AD, at a Roman fort on the fringe of the Sahara.'), ('48767303-6f43-4ddb-88e5-fb43ea3dfd89'::uuid, 'card_description', 'The first Roman mosaic in Britain with scenes from the Trojan War lies at this villa. Photos of the villa''s cropmarks were taken in June 2018 and later made widely available on Google Earth.'), ('5bb2f3b5-7bc6-4cf8-a3b4-cbb4b6e35595'::uuid, 'card_description', 'Described as Britain''s oldest road, this trackway has a stretch on a chalk ridge. Iron Age people built hillforts along the track, and that stretch runs to the Thames at the Goring Gap.'), ('679e85b1-245b-40bc-b815-8cd1ae71ee12'::uuid, 'card_description', 'Swimming and diving are banned over this island''s ruins. The partly submerged ruins belong to the ancient settlement of Dolichiste, and the area was declared specially protected in 1990.'), ('6cc9e902-c82f-4b21-9f36-41c2b783cebc'::uuid, 'card_description', 'Legal assemblies gathered at this crossroads of major trade routes. The routes linked Lake Malar communities with the north, and the country''s largest burial mound rises nearby.'), ('728762be-061a-4f8a-b03f-980153495b02'::uuid, 'card_description', 'When Constantius Chlorus moved to the city, he renovated this Roman arena. The arena, dug into a hillside and built into what was then the city''s wall, could hold about 20,000 spectators.'), ('76cd8b60-c373-4f26-85ac-2827b0797b15'::uuid, 'card_description', 'Ahmose founded a new age for a unified land, ruled from this city. On the Nile''s east bank stand the temples of Karnak and Luxor; royal cemeteries spread over the west bank.'), ('817ff7b7-a814-405a-a5af-0ef173f07045'::uuid, 'card_description', 'A Baroque triumphal arch replaced the eastern tower of this Roman bridge in 1721. The western tower dates from a rebuild after a flood and bears the arms of the Catholic Monarchs.'), ('a3a38d98-16fc-464f-bbeb-c027813ef202'::uuid, 'card_description', 'Sculptures of Jupiter Dolichenus have been found in this ancient Roman settlement. In the 3rd century BC, the area was inhabited by a people called the Scordisci.'), ('a4057ca6-8123-45d9-b213-91e18a1b9193'::uuid, 'card_description', 'Some sixty-five rooms once ringed the courtyard of this large Roman villa. Its north wing holds most of the fine mosaics, floors among the most complete and intricate in the country.'), ('ac3877a0-04fc-4049-b918-ebf41b0a1501'::uuid, 'card_description', 'A pile of bones lies at the bottom of a cliff in this ruined city. Special spots were set aside for human sacrifice, and the remains of one young woman were found well preserved.'), ('f29afd0d-6fb8-4405-bee8-c1b17a6989e3'::uuid, 'card_description', 'A mound 15 metres high is the highest structure left at this Maya site. The mound dates to the Late Formative, when the site became a regional political center on the New River.'))
SELECT 'journal rows for the rollback stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s036-rollback'
UNION ALL
SELECT 'planned rows still holding the written value', count(*)::text
  FROM planned p JOIN card_stats t ON t.site_id = p.site_id
 WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM p.written::character varying
                ELSE false END
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
